"""Dangly biscuit ornament: wafer. GENERATED by make.py from
common.py + wafer_part.py - edit those, not this file."""
import math

import adsk.core
import adsk.fusion

from fusionhelper.buildkit import BuildCtx

FH_ATTEMPT = 1
FH_OPTS = {"liveness_budget_s": 180}
INTERFERENCE_ALLOWED = []

MM = 0.1  # art constants are written in mm; the API is cm


# ---- pure-python art generators (all coordinates mm) -------------------

def arc_pts(cx, cy, r, a0_deg, a1_deg, n):
    out = []
    for i in range(n + 1):
        a = math.radians(a0_deg + (a1_deg - a0_deg) * i / n)
        out.append((cx + r * math.cos(a), cy + r * math.sin(a)))
    return out


def stroke(centre, w):
    """Closed polygon of constant width w around an open centreline."""
    n = len(centre)
    left, right = [], []
    for i in range(n):
        x0, y0 = centre[max(i - 1, 0)]
        x1, y1 = centre[min(i + 1, n - 1)]
        dx, dy = x1 - x0, y1 - y0
        ln = math.hypot(dx, dy)
        nx, ny = -dy / ln, dx / ln
        x, y = centre[i]
        left.append((x + nx * w / 2, y + ny * w / 2))
        right.append((x - nx * w / 2, y - ny * w / 2))
    return left + right[::-1]


def stroke_round(centre, w, n=4):
    """Like stroke() but with semicircular ends, so a closed spline
    through the points is smooth all the way round."""
    body = stroke(centre, w)
    half = len(body) // 2
    left, right = body[:half], body[half:]

    def cap(p_from, p_to):
        mx, my = (p_from[0] + p_to[0]) / 2, (p_from[1] + p_to[1]) / 2
        a0 = math.degrees(math.atan2(p_from[1] - my, p_from[0] - mx))
        return arc_pts(mx, my, w / 2, a0, a0 - 180, n)[1:-1]

    return left + cap(left[-1], right[0]) + right + cap(right[-1], left[0])


def smile(cx, cy, r, w, half_span_deg=55, n=12):
    return stroke(arc_pts(cx, cy, r, 270 - half_span_deg,
                          270 + half_span_deg, n), w)


def capsule(ax, ay, bx, by, w, n=6, n_side=4):
    """Round-ended bar from A to B, width w. The straight sides carry
    intermediate points so a closed spline through the outline stays
    straight along them."""
    ang = math.degrees(math.atan2(by - ay, bx - ax))
    end_b = arc_pts(bx, by, w / 2, ang - 90, ang + 90, n)
    end_a = arc_pts(ax, ay, w / 2, ang + 90, ang + 270, n)

    def side(p, q):
        return [(p[0] + (q[0] - p[0]) * k / n_side,
                 p[1] + (q[1] - p[1]) * k / n_side)
                for k in range(1, n_side)]

    return end_b + side(end_b[-1], end_a[0]) + end_a + side(end_a[-1], end_b[0])


def spiral(cx, cy, r0, r1, turns, a0_deg, n):
    pts = []
    for i in range(n + 1):
        a = math.radians(a0_deg + 360.0 * turns * i / n)
        r = r0 + (r1 - r0) * i / n
        pts.append((cx + r * math.cos(a), cy + r * math.sin(a)))
    return pts


def in_poly(x, y, poly):
    inside = False
    for i in range(len(poly)):
        x0, y0 = poly[i - 1]
        x1, y1 = poly[i]
        if (y0 > y) != (y1 > y) and x < x0 + (x1 - x0) * (y - y0) / (y1 - y0):
            inside = not inside
    return inside


def mirror(poly, sx, sy):
    return [(x * sx, y * sy) for x, y in poly]


def clip_rect(poly, x0, y0, x1, y1):
    """Sutherland-Hodgman clip of a convex polygon to a rectangle."""
    def clip(pts, inside, cross):
        out = []
        for i in range(len(pts)):
            a, b = pts[i - 1], pts[i]
            ia, ib = inside(a), inside(b)
            if ia and ib:
                out.append(b)
            elif ia and not ib:
                out.append(cross(a, b))
            elif ib:
                out.append(cross(a, b))
                out.append(b)
        return out

    def xcross(xv):
        return lambda a, b: (xv, a[1] + (b[1] - a[1]) * (xv - a[0])
                             / (b[0] - a[0]))

    def ycross(yv):
        return lambda a, b: (a[0] + (b[0] - a[0]) * (yv - a[1])
                             / (b[1] - a[1]), yv)

    pts = list(poly)
    for inside, cross in (
            (lambda p: p[0] >= x0, xcross(x0)),
            (lambda p: p[0] <= x1, xcross(x1)),
            (lambda p: p[1] >= y0, ycross(y0)),
            (lambda p: p[1] <= y1, ycross(y1))):
        if len(pts) < 3:
            return []
        pts = clip(pts, inside, cross)
    clean = []
    for p in pts:
        if not clean or math.hypot(p[0] - clean[-1][0],
                                   p[1] - clean[-1][1]) > 1e-6:
            clean.append(p)
    if len(clean) > 1 and math.hypot(clean[0][0] - clean[-1][0],
                                     clean[0][1] - clean[-1][1]) < 1e-6:
        clean.pop()
    return clean


def poly_area(poly):
    s = 0.0
    for i in range(len(poly)):
        x0, y0 = poly[i - 1]
        x1, y1 = poly[i]
        s += x0 * y1 - x1 * y0
    return abs(s) / 2


# ---- Fusion helpers -----------------------------------------------------

def fillet_corners(ctx, body, radius_expr, name):
    """Round the four vertical corner edges of a rectangular slab."""
    coll = adsk.core.ObjectCollection.create()
    for e in body.edges:  # fusionhelper: allow R11 — collection add, not a document mutation
        bb = e.boundingBox
        if (bb.maxPoint.z - bb.minPoint.z > 0.1
                and abs(bb.maxPoint.x - bb.minPoint.x) < 1e-4
                and abs(bb.maxPoint.y - bb.minPoint.y) < 1e-4):
            coll.add(e)
    if coll.count != 4:
        raise RuntimeError("%s: %d corner edges" % (name, coll.count))
    v0 = body.volume
    fil = ctx.root.features.filletFeatures
    inp = fil.createInput()
    inp.edgeSetInputs.addConstantRadiusEdgeSet(
        coll, ctx.cbs(radius_expr), False)
    f = fil.add(inp)
    f.name = name
    ok = (adsk.fusion.FeatureHealthStates.HealthyFeatureHealthState,)
    if f.healthState not in ok or v0 - body.volume < 1e-4:
        raise RuntimeError("%s: health %s dv %.5f"
                           % (name, f.healthState, v0 - body.volume))


def ring_profile(sk):
    ring = adsk.core.ObjectCollection.create()
    for pr in sk.profiles:  # fusionhelper: allow R11 — collection add, not a document mutation
        if pr.profileLoops.count == 2:
            ring.add(pr)
    if ring.count != 1:
        raise RuntimeError("%s: %d ring profiles" % (sk.name, ring.count))
    return ring


def emboss(ctx, profs, target, name):
    """Bevelled raised relief: tapered join, relief_h high. The taper
    sign is measured (must narrow), never assumed."""
    prism = prof_area(profs) * ctx.val("relief_h")
    v0 = target.volume
    # Once a sign is known to narrow, only that sign is ever tried: the
    # widening sign self-intersects on tight strokes and raises
    # (ASM_INCONS_REL) instead of returning something checkable. So the
    # FIRST emboss of a build must be a simple shape (ring / frame).
    signs = ctx._resolved.get("emboss_sign",
                              ("-emboss_taper", "emboss_taper"))
    for taper in signs:
        adsk.doEvents()
        f = extrude(ctx, profs, ctx.ops.JoinFeatureOperation, "relief_h",
                    name + "_emboss", participants=[target], taper=taper)
        dv = target.volume - v0
        if 0.25 * prism < dv < 0.95 * prism:
            ctx._resolved["emboss_sign"] = (taper,)
            return
        f.deleteMe()
    raise RuntimeError("%s emboss never narrowed (prism %.5f)"
                       % (name, prism))


def top_edge_keys(body, z_cm):
    """Flat edges of `body` lying at height z_cm, keyed by plan bbox."""
    out = {}
    for e in body.edges:
        bb = e.boundingBox
        if (abs(bb.maxPoint.z - z_cm) < 1e-4
                and abs(bb.minPoint.z - z_cm) < 1e-4):
            out[(round(bb.minPoint.x, 4), round(bb.minPoint.y, 4),
                 round(bb.maxPoint.x, 4), round(bb.maxPoint.y, 4))] = e
    return out


def soften_new_tops(ctx, body, z_cm, before, radius_expr, name):
    """Round the top edges that appeared at z_cm since `before` was
    taken (i.e. the relief just embossed). Earlier, already-rounded
    relief keeps flat-top edges at the same height, so edges are
    selected by what is NEW, never by height alone."""
    coll = adsk.core.ObjectCollection.create()
    for key, e in top_edge_keys(body, z_cm).items():  # fusionhelper: allow R11 — collection add, not a document mutation
        if key not in before:
            coll.add(e)
    if coll.count < 1:
        raise RuntimeError("%s: no new top edges" % name)
    v0 = body.volume
    fil = ctx.root.features.filletFeatures
    inp = fil.createInput()
    inp.edgeSetInputs.addConstantRadiusEdgeSet(
        coll, ctx.cbs(radius_expr), True)
    f = fil.add(inp)
    f.name = name
    ok = (adsk.fusion.FeatureHealthStates.HealthyFeatureHealthState,)
    if f.healthState not in ok or v0 - body.volume < 1e-6:
        raise RuntimeError("%s: health %s dv %.6f"
                           % (name, f.healthState, v0 - body.volume))


def fillet_rims(ctx, body, radius_expr, name, z_cm, min_span_cm=3.0):
    """Fillet the body's flat outer rim at height z_cm. Edges are picked
    by predicate (R4): planar at that z and spanning most of the part.
    add() can succeed while the fillet errors, so health and volume are
    both checked."""
    coll = adsk.core.ObjectCollection.create()
    for e in body.edges:  # fusionhelper: allow R11 — collection add, not a document mutation
        bb = e.boundingBox
        if (abs(bb.maxPoint.z - z_cm) < 1e-4
                and abs(bb.minPoint.z - z_cm) < 1e-4
                and bb.maxPoint.x - bb.minPoint.x > min_span_cm):
            coll.add(e)
    if coll.count < 1:
        raise RuntimeError("%s: %d rim edges" % (name, coll.count))
    v0 = body.volume
    fil = ctx.root.features.filletFeatures
    inp = fil.createInput()
    inp.edgeSetInputs.addConstantRadiusEdgeSet(
        coll, ctx.cbs(radius_expr), True)
    f = fil.add(inp)
    f.name = name
    ok = (adsk.fusion.FeatureHealthStates.HealthyFeatureHealthState,)
    if f.healthState not in ok or v0 - body.volume < 1e-4:
        raise RuntimeError("%s: health %s dv %.5f"
                           % (name, f.healthState, v0 - body.volume))


def fixed_sketch(ctx, plane, name, z_cm, polys=(), circles=(), splines=()):
    """Fixed-art sketch: closed polylines and circles at mm coordinates,
    mapped through the sketch's own transform (R6), then fixed."""
    sk = ctx.root.sketches.add(plane)
    sk.name = name
    sk.isComputeDeferred = True
    lines = sk.sketchCurves.sketchLines
    for poly in polys:
        adsk.doEvents()
        pts = [sk.modelToSketchSpace(ctx.pt(x * MM, y * MM, z_cm))
               for x, y in poly]
        first = lines.addByTwoPoints(pts[0], pts[1])
        prev = first
        for k in range(2, len(pts)):
            adsk.doEvents()
            prev = lines.addByTwoPoints(prev.endSketchPoint, pts[k])
        lines.addByTwoPoints(prev.endSketchPoint, first.startSketchPoint)
    for (x, y, r) in circles:
        adsk.doEvents()
        sk.sketchCurves.sketchCircles.addByCenterRadius(
            sk.modelToSketchSpace(ctx.pt(x * MM, y * MM, z_cm)), r * MM)
    for sp_pts in splines:
        adsk.doEvents()
        coll = adsk.core.ObjectCollection.create()
        for x, y in sp_pts:  # fusionhelper: allow R11 — collection add, not a document mutation
            coll.add(sk.modelToSketchSpace(ctx.pt(x * MM, y * MM, z_cm)))
        spl = sk.sketchCurves.sketchFittedSplines.add(coll)
        spl.isClosed = True
    for c in sk.sketchCurves:
        adsk.doEvents()
        if not c.isFixed:
            c.isFixed = True
    for sp in sk.sketchPoints:
        adsk.doEvents()
        if sp.isFullyConstrained or sp.isFixed:
            continue
        sp.isFixed = True
    sk.isComputeDeferred = False
    want = len(polys) + len(circles) + len(splines)
    if sk.profiles.count != want:
        raise RuntimeError("%s: %d profiles, expected %d"
                           % (name, sk.profiles.count, want))
    return sk


def prof_area(profs):
    total = 0.0
    for i in range(profs.count):
        total += profs.item(i).areaProperties().area
    return total


def depth_cm(ctx, expr):
    return ctx.des.unitsManager.evaluateExpression(expr, "cm")


def extrude(ctx, profs, op, dist_expr, name, participants=None, taper=None):
    inp = ctx.extrudes.createInput(profs, op)
    ext = adsk.fusion.DistanceExtentDefinition.create(ctx.cbs(dist_expr))
    if taper is None:
        inp.setOneSideExtent(ext, ctx.dirs.PositiveExtentDirection)
    else:
        inp.setOneSideExtent(ext, ctx.dirs.PositiveExtentDirection,
                             ctx.cbs(taper))
    if participants is not None:
        inp.participantBodies = participants
    f = ctx.extrudes.add(inp)
    f.name = name
    return f


def new_bodies(ctx, profs, dist_expr, name):
    f = extrude(ctx, profs, ctx.ops.NewBodyFeatureOperation, dist_expr,
                name + "_extrude")
    bodies = [f.bodies.item(i) for i in range(f.bodies.count)]
    if not bodies:
        raise RuntimeError("%s made no body" % name)
    if len(bodies) == 1:
        bodies[0].name = name
    else:
        for i, b in enumerate(bodies):
            b.name = "%s_%d" % (name, i + 1)
    return bodies


def cut_up(ctx, profs, dist_expr, targets, name):
    """Cut upward (+normal) from the sketch plane; volume-validated."""
    want = prof_area(profs) * depth_cm(ctx, dist_expr)
    v0 = sum(b.volume for b in targets)
    extrude(ctx, profs, ctx.ops.CutFeatureOperation, dist_expr,
            name + "_cut", participants=targets)
    dv = v0 - sum(b.volume for b in targets)
    if dv < 0.5 * want:
        raise RuntimeError("%s cut removed %.5f of %.5f cm3"
                           % (name, dv, want))


def join_up(ctx, profs, dist_expr, target, name):
    want = prof_area(profs) * depth_cm(ctx, dist_expr)
    v0 = target.volume
    extrude(ctx, profs, ctx.ops.JoinFeatureOperation, dist_expr,
            name + "_join", participants=[target])
    dv = target.volume - v0
    if dv < 0.4 * want:
        raise RuntimeError("%s join added %.5f of %.5f cm3"
                           % (name, dv, want))


def inlay(ctx, sk, target, depth_expr, name, sink_expr=None):
    """Colour inlay: pocket the target, then fill the pocket floor with
    new bodies from the same profiles. With sink_expr the pocket is that
    much deeper than the inlay, so the colour sits recessed below the
    face (the sketch plane must be at face - sink - depth)."""
    profs = ctx.all_profiles(sk)
    pocket = depth_expr if sink_expr is None else (
        "(%s) + (%s)" % (sink_expr, depth_expr))
    cut_up(ctx, profs, pocket, [target], name)
    return new_bodies(ctx, ctx.all_profiles(sk), depth_expr, name)


def plane_at_y(ctx, expr, name, y_cm):
    """XZ-parallel datum at world y = y_cm. The offset sign is measured,
    never assumed (R6)."""
    for e in (expr, "-(%s)" % expr):
        adsk.doEvents()
        pin = ctx.planes.createInput()
        pin.setByOffset(ctx.root.xZConstructionPlane, ctx.cbs(e))
        pl = ctx.planes.add(pin)
        if abs(pl.geometry.origin.y - y_cm) < 1e-4:
            pl.name = name
            return pl
        pl.deleteMe()
    raise RuntimeError("no offset sign puts %s at y=%.3f" % (name, y_cm))


# ---- print-in-place ball-jointed legs ----------------------------------
# Printed with the biscuit on its back and both legs straight up. Fixed
# art (mm). Each leg: thigh (hip ball + rod + knee bowl) and shin (knee
# ball + rod). Balls are teardrops (45 deg cone underneath) so nothing
# starts on a shallow overhang; each ball tip sits one layer above its
# socket floor and thin break-away tabs hold the tower rigid while it
# prints. Sockets wrap 44 deg past the equator: ball 8.0 through a 6.16
# opening, so the joint cannot pull out, and the 4.8 slot lets the neck
# (4.0) swing 90 deg: hip slot towards the bottom edge, knee slot the
# same way so a seated shin hangs down.
J_BALL_R = 4.0
J_GAP = 0.3            # radial ball-to-socket clearance
J_CAV_R = J_BALL_R + J_GAP
J_OUT_R = 6.7          # knee bowl outer radius: 1.25 wall outside the tip
                       # channel (5.45); 7.2 made the custard's two bowls
                       # (hips 14 apart) clash by 1.7 mm3
J_RECESS_R = 4.1       # hip recess radius; tab corner reaches 3.90
                       # (3.9 recess + 3.7 tab clipped the wall, 0.01 mm3)
J_NECK_R = 2.0
J_ROD_R = 3.1
J_LIP = 3.0            # socket opening height above ball centre
J_SLOT_W = 4.8
J_SLOT_FLOOR = 2.6     # slot floor below ball centre
J_TAB = (3.0, 0.4)     # break-away tab width, height


def arc_rz(zc, r, lat0_deg, lat1_deg, n):
    out = []
    for i in range(n + 1):
        a = math.radians(lat0_deg + (lat1_deg - lat0_deg) * i / n)
        out.append((r * math.cos(a), zc + r * math.sin(a)))
    return out


def j_ball_lower(zc):
    """Teardrop ball from its flat tip up to the neck."""
    s = J_BALL_R * math.sqrt(2)
    neck_lat = math.degrees(math.acos(J_NECK_R / J_BALL_R))
    return ([(0.0, zc - s + 0.5), (0.5, zc - s + 0.5)]
            + arc_rz(zc, J_BALL_R, -45, neck_lat, 14)
            + [(J_NECK_R, zc + 7.0), (J_ROD_R, zc + 7.0 + J_ROD_R - J_NECK_R)])


def j_floor_z(zc):
    return zc - J_CAV_R * math.sqrt(2) + 0.7


def j_cavity_inner(zc):
    """Socket wall from the lip down to the flat floor (r, z)."""
    lip_lat = math.degrees(math.asin(J_LIP / J_CAV_R))
    return (arc_rz(zc, J_CAV_R, lip_lat, -45, 14)
            + [(0.7, j_floor_z(zc)), (0.0, j_floor_z(zc))])


def j_shin_profile(zk, z_end):
    return (j_ball_lower(zk)
            + [(J_ROD_R, z_end - 0.6), (J_ROD_R - 0.6, z_end), (0.0, z_end)])


def j_socket_cut_profile(zc):
    inner = j_cavity_inner(zc)
    return ([(0.0, zc + J_LIP + 8.0), (J_RECESS_R, zc + J_LIP + 8.0),
             (J_RECESS_R, zc + J_LIP)] + inner)


def revolve_rz(ctx, plane, name, pts_rz, cx_mm, y_mm, op, participants=None):
    """Revolve a closed (r, z) polygon about the vertical axis through
    (cx_mm, y_mm). The polygon must have exactly one edge on the axis."""
    sk = ctx.root.sketches.add(plane)
    sk.name = name + "_profile"
    sk.isComputeDeferred = True
    lines = sk.sketchCurves.sketchLines
    pts = [sk.modelToSketchSpace(ctx.pt((cx_mm + r) * MM, y_mm * MM, z * MM))
           for r, z in pts_rz]
    first = lines.addByTwoPoints(pts[0], pts[1])
    prev = first
    for k in range(2, len(pts)):
        adsk.doEvents()
        prev = lines.addByTwoPoints(prev.endSketchPoint, pts[k])
    lines.addByTwoPoints(prev.endSketchPoint, first.startSketchPoint)
    for c in sk.sketchCurves:
        adsk.doEvents()
        if not c.isFixed:
            c.isFixed = True
    for sp in sk.sketchPoints:
        adsk.doEvents()
        if sp.isFullyConstrained or sp.isFixed:
            continue
        sp.isFixed = True
    sk.isComputeDeferred = False
    if sk.profiles.count != 1:
        raise RuntimeError("%s: %d profiles" % (name, sk.profiles.count))
    axis = None
    for ln in sk.sketchCurves.sketchLines:
        s = sk.sketchToModelSpace(ln.startSketchPoint.geometry)
        e = sk.sketchToModelSpace(ln.endSketchPoint.geometry)
        if (abs(s.x - cx_mm * MM) < 1e-5 and abs(e.x - cx_mm * MM) < 1e-5
                and abs(s.z - e.z) > 1e-4):
            axis = ln
    if axis is None:
        raise RuntimeError("%s: no axis line" % name)
    rev = ctx.root.features.revolveFeatures
    rinp = rev.createInput(sk.profiles.item(0), axis, op)
    rinp.setAngleExtent(False, ctx.cbs("360 deg"))
    if participants is not None:
        rinp.participantBodies = participants
    f = rev.add(rinp)
    f.name = name
    return f


def tip_channel(ctx, plane, name, cx_mm, y_mm, zc, bodies):
    """Relief for the teardrop tip. The ball's 45 deg underside reaches
    5.16 mm from the ball centre, outside the 4.3 socket sphere, so a
    snug socket jams the joint (measured: 3.5 mm3 clash through the
    swing). This sweeps the tip pocket about the hinge (X) axis from
    straight-down round to 135 deg on the +Y side, so the tip can follow
    a 90 deg swing; stopping at 135 deg makes the end face a 45 deg
    roof. The sweep direction is measured by point containment."""
    s2 = J_CAV_R * math.sqrt(2)
    # Hexagon, 0.14 mm proud of the pocket cone everywhere and with its
    # top edge well inside the socket sphere. Measured the hard way: a
    # top edge outside the sphere leaves 0.38 mm slivers hanging
    # (probe_face), and sides exactly ON the pocket cone (tangent to
    # the sphere) made the boolean return garbage volumes.
    c = s2 + 0.2
    wide, top, floor = 3.3, 2.0, 5.45
    quad = [(-wide, zc - top), (wide, zc - top), (wide, zc - (c - wide)),
            (c - floor, zc - floor), (-(c - floor), zc - floor),
            (-wide, zc - (c - wide))]
    sk = ctx.root.sketches.add(plane)
    sk.name = name + "_profile"
    lines = sk.sketchCurves.sketchLines
    pts = [sk.modelToSketchSpace(ctx.pt((cx_mm + x) * MM, y_mm * MM, z * MM))
           for x, z in quad]
    first = lines.addByTwoPoints(pts[0], pts[1])
    prev = first
    for k in range(2, len(pts)):
        adsk.doEvents()
        prev = lines.addByTwoPoints(prev.endSketchPoint, pts[k])
    lines.addByTwoPoints(prev.endSketchPoint, first.startSketchPoint)
    axis = lines.addByTwoPoints(
        sk.modelToSketchSpace(ctx.pt((cx_mm - 3) * MM, y_mm * MM, zc * MM)),
        sk.modelToSketchSpace(ctx.pt((cx_mm + 3) * MM, y_mm * MM, zc * MM)))
    for c in sk.sketchCurves:
        adsk.doEvents()
        if not c.isFixed:
            c.isFixed = True
    for sp in sk.sketchPoints:
        adsk.doEvents()
        if sp.isFullyConstrained or sp.isFixed:
            continue
        sp.isFixed = True
    if sk.profiles.count != 1:
        raise RuntimeError("%s: %d profiles" % (name, sk.profiles.count))
    probe = ctx.pt(cx_mm * MM, (y_mm + 4.9) * MM, zc * MM)
    inside = adsk.fusion.PointContainment.PointInsidePointContainment
    rev = ctx.root.features.revolveFeatures
    for ang in ("135 deg", "-135 deg"):
        adsk.doEvents()
        rinp = rev.createInput(sk.profiles.item(0), axis,
                               ctx.ops.CutFeatureOperation)
        rinp.setAngleExtent(False, ctx.cbs(ang))
        rinp.participantBodies = bodies
        v0 = sum(b.volume for b in bodies)
        f = rev.add(rinp)
        dv = v0 - sum(b.volume for b in bodies)
        if (all(b.pointContainment(probe) != inside for b in bodies)
                and 0.005 < dv < 0.25):
            f.name = name
            return
        print("FH %s %s rejected dv %.5f" % (name, ang, dv))
        f.deleteMe()
    raise RuntimeError("%s: neither sweep direction opened +Y" % name)


CHEEK_H = 0.9      # rosy cheek dome height above the face, mm


def domed_cheeks(ctx, target, cheeks, face_z, inlay_mm):
    """Rosy cheeks as true spherical caps: a plug filling the inlay
    pocket with a spherical cap rising CHEEK_H above the face. Fixed art
    in z (revolved profile), so the pocket is cut by a revolve at the
    same fixed heights and open upward: a pocket on a parameter-driven
    plane moved under a thickness edit and buried the plug (verify:
    edit.introduces_clash). cheeks = [(x, y, r)] mm, all at one y."""
    y = cheeks[0][1]
    pl = plane_at_y(ctx, "%g mm" % abs(y), "cheek_plane", y * MM)
    out = []
    for n, (x, _y, r) in enumerate(cheeks):
        adsk.doEvents()
        big_r = (r * r + CHEEK_H * CHEEK_H) / (2 * CHEEK_H)
        zc = face_z + CHEEK_H - big_r
        a0 = math.degrees(math.asin((face_z - zc) / big_r))
        prof = ([(0.0, face_z - inlay_mm), (r, face_z - inlay_mm)]
                + arc_rz(zc, big_r, a0, 90, 10))
        prof[-1] = (0.0, face_z + CHEEK_H)
        pocket = [(0.0, face_z - inlay_mm), (r, face_z - inlay_mm),
                  (r, face_z + 5.0), (0.0, face_z + 5.0)]
        v0 = target.volume
        revolve_rz(ctx, pl, "cheek_pocket_%d" % (n + 1), pocket, x, y,
                   ctx.ops.CutFeatureOperation, [target])
        if v0 - target.volume < 1e-4:
            raise RuntimeError("cheek pocket %d cut nothing" % (n + 1))
        f = revolve_rz(ctx, pl, "cheek_%d" % (n + 1), prof, x, y,
                       ctx.ops.NewBodyFeatureOperation)
        body = f.bodies.item(0)
        body.name = "cheek_%d" % (n + 1)
        out.append(body)
    return out


def cut_some(ctx, profs, dist_expr, targets, name, min_dv):
    v0 = sum(b.volume for b in targets)
    extrude(ctx, profs, ctx.ops.CutFeatureOperation, dist_expr,
            name + "_cut", participants=targets)
    dv = v0 - sum(b.volume for b in targets)
    if dv < min_dv:
        raise RuntimeError("%s cut removed only %.5f cm3" % (name, dv))


def j_tabs(cx, cy):
    """One wide break-away tab on the +Y side of a neck. Measured
    (probe_joints): tabs on the +-X sides stay on the neck as nubs and
    foul the socket wall through the 90 deg swing; a +Y nub rides over
    the rim and ends above the slot, so it never touches anything."""
    hw = J_TAB[0] / 2
    return [[(cx - hw, cy + 1.5), (cx + hw, cy + 1.5),
             (cx + hw, cy + 3.6), (cx - hw, cy + 3.6)]]


J_LEG = 27.0           # hip centre to leg end (single-segment leg)


def jointed_legs(ctx, bodies, hip_x, hip_y, face_z):
    """Cut two hip sockets into `bodies` and build two print-in-place
    single-segment legs standing in them. hip_x / hip_y / face_z in mm.

    Print feedback 2026-11-22: (1) hips near the front face made the
    biscuit over-balance, so the ball now sits at MID thickness with a
    well down from the face; (2) the two-segment leg was too long and
    the part that survived (hip to knee) stood and sat well, so the knee
    joint and shin are gone. Returns (legs, zc, z_end)."""
    zc = face_z / 2.0
    z_end = zc + J_LEG
    new_op = ctx.ops.NewBodyFeatureOperation
    pl = plane_at_y(ctx, "%g mm" % abs(hip_y), "hip_plane", hip_y * MM)
    v0 = sum(b.volume for b in bodies)
    legs = []
    for n, sx in enumerate((1, -1)):
        adsk.doEvents()
        cx = sx * hip_x
        tag = "_%d" % (n + 1)
        revolve_rz(ctx, pl, "hip_socket" + tag, j_socket_cut_profile(zc),
                   cx, hip_y, ctx.ops.CutFeatureOperation, bodies)
        fl = revolve_rz(ctx, pl, "leg" + tag, j_shin_profile(zc, z_end),
                        cx, hip_y, new_op)
        leg = fl.bodies.item(0)
        leg.name = "leg" + tag
        tip_channel(ctx, pl, "hip_tip_channel" + tag, cx, hip_y, zc,
                    bodies)
        legs.append(leg)
    if v0 - sum(b.volume for b in bodies) < 0.3:
        raise RuntimeError("hip sockets removed too little")
    # hip slots: from each socket out through the bottom edge
    hw = J_SLOT_W / 2
    zs = zc - J_SLOT_FLOOR
    pl_hs = ctx.plane_at_z("%g mm" % zs, "hip_slot_plane")
    sk_hs = fixed_sketch(
        ctx, pl_hs, "hip_slots", zs * MM,
        polys=[[(sx * hip_x - hw, hip_y - 14.0), (sx * hip_x + hw, hip_y - 14.0),
                (sx * hip_x + hw, hip_y), (sx * hip_x - hw, hip_y)]
               for sx in (1, -1)])
    cut_some(ctx, ctx.all_profiles(sk_hs), "%g mm" % (face_z - zs + 4.0),
             bodies, "hip_slots", 0.05)
    # The slot is only neck-wide (4.8) around the ball, which is what
    # retains it. With the hip at mid thickness the 6.2 mm shaft also
    # travels through the body on its way down (measured: 2.8 mm3 clash
    # at 30 deg), so the slot widens to shaft width (a) everywhere above
    # the socket lip and (b) at every height beyond the socket wall.
    hs = J_ROD_R + 0.4
    pl_ht = ctx.plane_at_z("%g mm" % (zc + J_LIP), "hip_tab_plane")
    sk_wa = fixed_sketch(
        ctx, pl_ht, "shaft_slots_upper", (zc + J_LIP) * MM,
        polys=[[(sx * hip_x - hs, hip_y - 14.0), (sx * hip_x + hs, hip_y - 14.0),
                (sx * hip_x + hs, hip_y), (sx * hip_x - hs, hip_y)]
               for sx in (1, -1)])
    cut_some(ctx, ctx.all_profiles(sk_wa),
             "%g mm" % (face_z - zc - J_LIP + 4.0), bodies,
             "shaft_slots_upper", 0.02)
    y_out = hip_y - J_CAV_R - 0.3
    sk_wb = fixed_sketch(
        ctx, pl_hs, "shaft_slots_outer", zs * MM,
        polys=[[(sx * hip_x - hs, hip_y - 14.0), (sx * hip_x + hs, hip_y - 14.0),
                (sx * hip_x + hs, y_out), (sx * hip_x - hs, y_out)]
               for sx in (1, -1)])
    cut_some(ctx, ctx.all_profiles(sk_wb), "%g mm" % (face_z - zs + 4.0),
             bodies, "shaft_slots_outer", 0.005)
    # one break-away tab per leg, on the floor of the socket well
    for n, sx in enumerate((1, -1)):
        adsk.doEvents()
        tag = "_%d" % (n + 1)
        sk_t = fixed_sketch(ctx, pl_ht, "hip_tabs" + tag, (zc + J_LIP) * MM,
                            polys=j_tabs(sx * hip_x, hip_y))
        join_up(ctx, ctx.all_profiles(sk_t), "%g mm" % J_TAB[1],
                legs[n], "hip_tabs" + tag)
    print("FH jointed legs ok: leg %.3f cm3, hip z %.1f, top z %.1f"
          % (legs[0].volume, zc, z_end))
    return legs, zc, z_end


# ---- break-away print brace -------------------------------------------
# The legs print as 60 mm towers on ball joints; one tab and a tip weld
# did not hold them (printed 2026-11-22: leg wobbled). This is a
# sacrificial wall on the bed just outside the bottom edge, buttressed
# behind, with 45 deg struts up to each thigh and shin rod. Struts touch
# the rods (tangent, zero overlap) so the slicer fuses them; everything
# rises at 45 deg or steeper, nothing bridges.
BR_T = 2.0          # wall and buttress thickness (1.2 got knocked loose)
BR_PAD = (0.8, 3.0)  # bed pad thickness, margin round the footprint
BR_NIB = (0.8, 0.9)  # strut width (x), height (z)
BR_FOOT = 14.0      # buttress depth on the bed


def plane_at_x(ctx, expr, name, x_cm):
    """YZ-parallel datum at world x = x_cm; offset sign measured (R6)."""
    for e in (expr, "-(%s)" % expr):
        adsk.doEvents()
        pin = ctx.planes.createInput()
        pin.setByOffset(ctx.root.yZConstructionPlane, ctx.cbs(e))
        pl = ctx.planes.add(pin)
        if abs(pl.geometry.origin.x - x_cm) < 1e-4:
            pl.name = name
            return pl
        pl.deleteMe()
    raise RuntimeError("no offset sign puts %s at x=%.3f" % (name, x_cm))


def sketch_xyz(ctx, plane, name, polys):
    """Fixed closed polylines given as (x, y, z) mm points on `plane`."""
    sk = ctx.root.sketches.add(plane)
    sk.name = name
    lines = sk.sketchCurves.sketchLines
    for poly in polys:
        adsk.doEvents()
        pts = [sk.modelToSketchSpace(ctx.pt(x * MM, y * MM, z * MM))
               for x, y, z in poly]
        first = lines.addByTwoPoints(pts[0], pts[1])
        prev = first
        for k in range(2, len(pts)):
            adsk.doEvents()
            prev = lines.addByTwoPoints(prev.endSketchPoint, pts[k])
        lines.addByTwoPoints(prev.endSketchPoint, first.startSketchPoint)
    for c in sk.sketchCurves:
        adsk.doEvents()
        if not c.isFixed:
            c.isFixed = True
    for sp in sk.sketchPoints:
        adsk.doEvents()
        if sp.isFullyConstrained or sp.isFixed:
            continue
        sp.isFixed = True
    if sk.profiles.count != len(polys):
        raise RuntimeError("%s: %d profiles, expected %d"
                           % (name, sk.profiles.count, len(polys)))
    return sk


def sym_join(ctx, sk, width_expr, target, name):
    v0 = target.volume
    inp = ctx.extrudes.createInput(ctx.all_profiles(sk),
                                   ctx.ops.JoinFeatureOperation)
    inp.setSymmetricExtent(ctx.cbs(width_expr), True)
    inp.participantBodies = [target]
    f = ctx.extrudes.add(inp)
    f.name = name
    if target.volume - v0 < 1e-4:
        raise RuntimeError("%s joined nothing" % name)


def print_brace(ctx, hip_x, hip_y, zc, z_end, edge_y):
    """edge_y: the biscuit's outermost bottom-edge y (mm, negative)."""
    z_top = z_end - 1.0
    yw = edge_y - 0.6
    half = hip_x + 6.0
    skw = fixed_sketch(ctx, ctx.root.xYConstructionPlane, "brace_wall", 0,
                       polys=[[(-half, yw - BR_T), (half, yw - BR_T),
                               (half, yw), (-half, yw)]])
    brace = new_bodies(ctx, ctx.all_profiles(skw), "%g mm" % z_top,
                       "print_brace")[0]
    y_leg = hip_y - J_ROD_R
    gap = y_leg - yw
    # the rod is straight from zc + 8.1 up to the end chamfer
    heights = (zc + 10.5, zc + 17.0, z_end - 2.5)
    for n, sx in enumerate((1, -1)):
        adsk.doEvents()
        x = sx * hip_x
        pl = plane_at_x(ctx, "%g mm" % hip_x, "brace_plane_%d" % (n + 1),
                        x * MM)
        rib = [(x, yw - BR_T + 0.3, 0.0), (x, yw - BR_T - BR_FOOT, 0.0),
               (x, yw - BR_T + 0.3, z_top)]
        skr = sketch_xyz(ctx, pl, "brace_rib_%d" % (n + 1), [rib])
        sym_join(ctx, skr, "%g mm" % BR_T, brace,
                 "brace_rib_join_%d" % (n + 1))
        nibs = []
        for z0 in heights:
            nibs.append([(x, yw - 0.3, z0 - gap - 0.3),
                         (x, yw - 0.3, z0 - gap - 0.3 + BR_NIB[1]),
                         (x, y_leg, z0 + BR_NIB[1]),
                         (x, y_leg, z0)])
        skn = sketch_xyz(ctx, pl, "brace_struts_%d" % (n + 1), nibs)
        sym_join(ctx, skn, "%g mm" % BR_NIB[0], brace,
                 "brace_strut_join_%d" % (n + 1))
    # Flat pad on the bed under the whole brace. Printed 2026-11-22: the
    # wall and two thin buttress edges alone did not grip the bed and the
    # brace kept being dislodged.
    m = BR_PAD[1]
    pad = [(-half - m, yw - BR_T - BR_FOOT - m), (half + m, yw - BR_T - BR_FOOT - m),
           (half + m, yw), (-half - m, yw)]
    skp = fixed_sketch(ctx, ctx.root.xYConstructionPlane, "brace_pad", 0,
                       polys=[pad])
    join_up(ctx, ctx.all_profiles(skp), "%g mm" % BR_PAD[0], brace,
            "brace_pad")
    print("FH brace pad %.0f x %.0f mm" % (2 * (half + m), BR_T + BR_FOOT + m))
    print("FH print brace ok %.3f cm3, wall y %.1f, strut reach %.1f"
          % (brace.volume, yw, gap))
    return brace


def feet(ctx, foot_x, foot_y):
    """Two push-on biscuit feet with piped-cream tops. Positions in mm."""
    root = ctx.root
    skd = root.sketches.add(root.xYConstructionPlane)
    skd.name = "foot_discs"
    for sx in (1, -1):
        adsk.doEvents()
        ctx.bound_circle(skd, (sx * foot_x * MM, foot_y * MM, 0), 0.9,
                         "18 mm", x_pos="%g mm" % foot_x,
                         v_pos="%g mm" % abs(foot_y))
    discs = new_bodies(ctx, ctx.all_profiles(skd), "foot_disc_h",
                       "foot_disc")
    if len(discs) != 2:
        raise RuntimeError("foot discs %d" % len(discs))
    # bevel both rims of each foot biscuit (before the cream and socket,
    # while each disc has exactly two circular edges)
    fil = root.features.filletFeatures
    for n, disc in enumerate(discs):
        adsk.doEvents()
        for z_cm, expr, nm in ((ctx.val("foot_disc_h"), "foot_fillet", "top"),
                               (0.0, "foot_fillet * 0.4", "bed")):
            adsk.doEvents()
            coll = adsk.core.ObjectCollection.create()
            for e in disc.edges:  # fusionhelper: allow R11 — collection add, not a document mutation
                bb = e.boundingBox
                if (abs(bb.maxPoint.z - z_cm) < 1e-4
                        and abs(bb.minPoint.z - z_cm) < 1e-4):
                    coll.add(e)
            if coll.count != 1:
                raise RuntimeError("foot %d %s rim edges %d"
                                   % (n + 1, nm, coll.count))
            v0 = disc.volume
            finp = fil.createInput()
            finp.edgeSetInputs.addConstantRadiusEdgeSet(
                coll, ctx.cbs(expr), True)
            ff = fil.add(finp)
            ff.name = "foot_%s_bevel_%d" % (nm, n + 1)
            if (ff.healthState
                    != adsk.fusion.FeatureHealthStates.HealthyFeatureHealthState
                    or v0 - disc.volume < 1e-5):
                raise RuntimeError("foot %d %s bevel failed" % (n + 1, nm))
    plc = ctx.plane_at_z("foot_disc_h", "foot_cream_plane")
    zc = ctx.val("foot_disc_h")
    stars = []
    for sx in (1, -1):
        star = []
        for i in range(16):
            r = 7.5 if i % 2 == 0 else 5.8   # inside the bevelled rim
            a = math.radians(i * 22.5)
            star.append((sx * foot_x + r * math.cos(a),
                         foot_y + r * math.sin(a)))
        stars.append(star)
    skc = fixed_sketch(ctx, plc, "foot_cream_stars", zc, polys=stars)
    prism = prof_area(ctx.all_profiles(skc)) * ctx.val("foot_cream_h")
    creams = None
    for taper in ("-12 deg", "12 deg"):
        adsk.doEvents()
        f = extrude(ctx, ctx.all_profiles(skc),
                    ctx.ops.NewBodyFeatureOperation, "foot_cream_h",
                    "foot_cream_extrude", taper=taper)
        got = [f.bodies.item(i) for i in range(f.bodies.count)]
        if sum(b.volume for b in got) < 0.95 * prism:
            creams = got
            break
        f.deleteMe()
    if creams is None or len(creams) != 2:
        raise RuntimeError("foot cream taper never narrowed")
    for i, b in enumerate(creams):
        b.name = "foot_cream_%d" % (i + 1)
    pls = ctx.plane_at_z("foot_disc_h + foot_cream_h", "foot_top_plane")
    zs = zc + ctx.val("foot_cream_h")
    sks = root.sketches.add(pls)
    sks.name = "foot_sockets"
    for sx in (1, -1):
        adsk.doEvents()
        ctx.bound_circle(sks, (sx * foot_x * MM, foot_y * MM, zs), 0.325,
                         "foot_hole_d", x_pos="%g mm" % foot_x,
                         v_pos="%g mm" % abs(foot_y))
    f = ctx.sym_cut(ctx.all_profiles(sks),
                    "2 * (foot_cream_h + foot_disc_h / 2)",
                    discs + creams, min_vol_cm3=0.1)
    f.name = "foot_socket_cut"
    print("FH feet ok")


def bevel_params(ctx, taper_deg=30):
    up, cbs = ctx.up, ctx.cbs
    up.add("edge_fillet", cbs("1.5 mm"), "mm", "upward-facing rim bevel")
    up.add("under_fillet", cbs("0.5 mm"), "mm", "downward-facing rim bevel")
    up.add("relief_h", cbs("0.8 mm"), "mm", "embossed pattern height")
    up.add("emboss_taper", cbs("%g deg" % taper_deg), "deg",
           "embossing bevel angle")


def common_params(ctx):
    up, cbs = ctx.up, ctx.cbs
    up.add("inlay_d", cbs("0.6 mm"), "mm", "colour inlay depth")
    # 6.5 printed loose on the 6.2 mm leg end (2026-11-22); 6.3 for a
    # push fit. Tune here or in Fusion - it is a live parameter.
    up.add("foot_hole_d", cbs("6.3 mm"), "mm",
           "foot socket dia (leg end is 6.2)")
    up.add("face_sink", cbs("1.2 mm"), "mm",
           "eyes and smile recessed below the face")
    up.add("foot_fillet", cbs("1.2 mm"), "mm", "foot biscuit rim bevel")
    up.add("foot_disc_h", cbs("6 mm"), "mm", "foot biscuit height")
    up.add("foot_cream_h", cbs("7 mm"), "mm", "foot cream height")


# ============================ pink wafer =================================
# Printed flat, face up. Bodies: wafer_1..4 (pink sheets, the top one
# carrying the lattice and face), wafer_cream_1..3 (white layers),
# ink_*, cheek_*, feet, legs.

WF_W, WF_H = 35.0, 75.0
WF_PITCH = 8.0      # lattice line spacing along x, mm
WF_LINE_W = 1.2
WF_PANELS = ((-14.5, 11.0, 14.5, 34.5), (-14.5, -34.5, 14.5, -9.0))


def wf_lattice(sign):
    """Diagonal ridges x + sign*y = c, clipped to both panels."""
    polys = []
    half = WF_LINE_W / 2 * math.sqrt(2)   # half-width measured along x
    for (x0, y0, x1, y1) in WF_PANELS:
        k = -12
        while k <= 12:
            c = k * WF_PITCH + (y0 + y1) / 2 * sign
            big = 200.0
            # strip between x + sign*y = c - half and c + half
            quad = [(c - half - sign * (-big), -big),
                    (c + half - sign * (-big), -big),
                    (c + half - sign * big, big),
                    (c - half - sign * big, big)]
            poly = clip_rect(quad, x0, y0, x1, y1)
            if len(poly) >= 3 and poly_area(poly) > 4.0:
                polys.append(poly)
            k += 1
    return polys


def run(_context: str):
    app = adsk.core.Application.get()
    ctx = BuildCtx(app)
    root = ctx.root
    up, cbs = ctx.up, ctx.cbs

    up.add("wafer_t", cbs("16 mm"), "mm", "wafer thickness")
    up.add("groove_d", cbs("0.8 mm"), "mm", "layer groove depth")
    up.add("groove_h", cbs("1 mm"), "mm", "layer groove height")
    up.add("relief_h", cbs("0.8 mm"), "mm", "lattice ridge height")
    common_params(ctx)
    print("FH params added")

    t_cm = ctx.val("wafer_t")
    inlay_cm = ctx.val("inlay_d")
    gd = ctx.val("groove_d")
    hw, hh = WF_W / 2 * MM, WF_H / 2 * MM

    # Four pink wafer sheets with three white cream layers between them.
    # The cream is set back groove_d from the edge, so the layer lines
    # read as white grooves round the sides.
    def slab(z_expr, h_expr, name, inset):
        z_cm = depth_cm(ctx, z_expr)
        if z_cm < 1e-9:
            plane = root.xYConstructionPlane
        else:
            plane = ctx.plane_at_z(z_expr, name + "_plane")
        sk = root.sketches.add(plane)
        sk.name = name + "_outline"
        if inset:
            w_e = "(%g mm - 2 * groove_d)" % WF_W
            h_e = "(%g mm - 2 * groove_d)" % WF_H
            shrink = gd
        else:
            w_e = "%g mm" % WF_W
            h_e = "%g mm" % WF_H
            shrink = 0.0
        ctx.bound_rect2(sk, (0, 0, z_cm), hw - shrink, hh - shrink,
                        u_size=w_e, v_size=h_e,
                        u_pos=("0 mm", w_e + " / 2"),
                        v_pos=("0 mm", h_e + " / 2"))
        return new_bodies(ctx, ctx.all_profiles(sk), h_expr, name)[0]

    sheets, creams = [], []
    for k in range(4):
        adsk.doEvents()
        z0 = "0 mm" if k == 0 else "wafer_t * %d / 4 + groove_h / 2" % k
        h = ("wafer_t / 4 - groove_h / 2" if k in (0, 3)
             else "wafer_t / 4 - groove_h")
        sheets.append(slab(z0, h, "wafer_%d" % (k + 1), False))
        if k < 3:
            creams.append(slab("wafer_t * %d / 4 - groove_h / 2" % (k + 1),
                               "groove_h", "wafer_cream_%d" % (k + 1), True))
    wafer = sheets[3]          # the face sheet
    pieces = sheets + creams
    print("FH sheets %.3f cream %.3f" % (sum(b.volume for b in sheets),
                                         sum(b.volume for b in creams)))

    # raised lattice, one sketch per diagonal direction so every ridge
    # is its own profile (crossing strokes in one sketch fill diamonds)
    pl_top = ctx.plane_at_z("wafer_t", "wafer_top_plane")
    for sign, nm in ((1, "lattice_fwd"), (-1, "lattice_back")):
        adsk.doEvents()
        skl = fixed_sketch(ctx, pl_top, nm, t_cm, polys=wf_lattice(sign))
        join_up(ctx, ctx.all_profiles(skl), "relief_h", wafer, nm)
    print("FH lattice %.3f" % wafer.volume)

    # face inlays in the plain band
    pl_face = ctx.plane_at_z("wafer_t - face_sink - inlay_d", "face_plane")
    zf = t_cm - ctx.val("face_sink") - inlay_cm
    sk_ink = fixed_sketch(
        ctx, pl_face, "face_ink", zf,
        polys=[smile(0, 4.0, 4.6, 1.2)],
        circles=[(6.0, 5.0, 1.1), (-6.0, 5.0, 1.1)])
    inlay(ctx, sk_ink, wafer, "inlay_d", "ink", sink_expr="face_sink")
    domed_cheeks(ctx, wafer, [(11.5, 1.5, 2.0), (-11.5, 1.5, 2.0)], t_cm / MM, inlay_cm / MM)
    print("FH face ok")

    _legs, zc, z_end = jointed_legs(ctx, pieces, 8.0, -32.0, t_cm / MM)
    print_brace(ctx, 8.0, -32.0, zc, z_end, -WF_H / 2)
    feet(ctx, 12, -74)
    print("FH BUILD OK: %d bodies" % root.bRepBodies.count)
